import uuid
from decimal import Decimal

from django.db import models
from django.utils import timezone

from apps.accounts.models import User
from apps.bookings.models import Booking, Ticket
from apps.fleet.models import SeatType
from apps.flights.models import Flight


class ProposalStatus(models.TextChoices):
    PENDING_CONFIRMATION = "PENDING_CONFIRMATION", "Pending Confirmation"
    CONFIRMED = "CONFIRMED", "Confirmed"
    REJECTED = "REJECTED", "Rejected"


class RebookingProposal(models.Model):
    """Human-in-the-loop rebooking proposal generated by the AI Disruption Copilot.

    The AI agent can ONLY create PENDING_CONFIRMATION proposals; executing the
    actual booking/balance mutation requires explicit passenger or Supervisor confirmation.
    """

    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    user = models.ForeignKey(User, on_delete=models.CASCADE, related_name="rebooking_proposals")
    original_ticket = models.ForeignKey(
        Ticket, on_delete=models.CASCADE, related_name="rebooking_proposals"
    )
    proposed_flight = models.ForeignKey(
        Flight, on_delete=models.PROTECT, related_name="proposed_rebookings"
    )
    proposed_seat_type = models.ForeignKey(SeatType, on_delete=models.PROTECT)
    fee_waived = models.BooleanField(default=False)
    fare_difference = models.DecimalField(
        max_digits=12, decimal_places=2, default=Decimal("0.00")
    )
    status = models.CharField(
        max_length=28,
        choices=ProposalStatus.choices,
        default=ProposalStatus.PENDING_CONFIRMATION,
        db_index=True,
    )
    provider = models.CharField(max_length=32, default="deterministic")
    rationale = models.TextField(blank=True)
    policy_citations = models.JSONField(default=list, blank=True)
    tool_trace = models.JSONField(default=list, blank=True)
    new_booking = models.ForeignKey(
        Booking,
        null=True,
        blank=True,
        on_delete=models.SET_NULL,
        related_name="copilot_proposals",
    )
    created_at = models.DateTimeField(default=timezone.now)
    confirmed_at = models.DateTimeField(null=True, blank=True)

    class Meta:
        ordering = ["-created_at"]

    def __str__(self) -> str:
        return (
            f"Proposal({self.original_ticket.ticket_code} -> "
            f"{self.proposed_flight.flight_number}, {self.status})"
        )
